import{Z as e,e as n,f as o,a0 as a}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"N8n","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/automations/n8n.md","filePath":"integrations/automations/n8n.md","lastUpdated":1780377007000}'),i={name:"integrations/automations/n8n.md"};function s(r,t,l,h,c,d){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="n8n" tabindex="-1">N8n <a class="header-anchor" href="#n8n" aria-label="Permalink to &quot;N8n&quot;">​</a></h1><p>Connect n8n to pass submitted answers to an automated workflow. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Automations</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>n8n</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-n8n-api" tabindex="-1">Step 2. Connect to the N8n API <a class="header-anchor" href="#step-2-connect-to-the-n8n-api" aria-label="Permalink to &quot;Step 2. Connect to the N8n API&quot;">​</a></h3><ol><li>Go to the <a href="https://n8n.cloud/" target="_blank">n8n Dashboard</a> or your self-hosted instance.</li><li>Create a new workflow from scratch.</li><li>Add a <strong>Webhook</strong> trigger node to your canvas.</li><li>Set the HTTP Method to <strong>POST</strong>.</li><li>Click <strong>Save</strong>, then copy the <strong>Test URL</strong> or <strong>Production URL</strong> from the Webhook node.</li></ol><h3 id="step-3-form-setting-test-payload" tabindex="-1">Step 3. Form Setting &amp; Test Payload <a class="header-anchor" href="#step-3-form-setting-test-payload" aria-label="Permalink to &quot;Step 3. Form Setting &amp; Test Payload&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination workflow or URL supported by this integration and map the submitted values it needs. Use a test destination while checking the connection.</li><li>Click <strong>Save</strong> to save the form.</li><li>Click on the <strong>Send Test Payload</strong> button to send dummy content to the URL.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Inspect the receiving workflow’s run history or request log. Check both the received values and the outcome of any following steps.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',11)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
